use crate::{Story, StoryError};

pub fn apply(story: &mut Story) -> Result<(), StoryError> {
    isaiah(story)?;
    jeremiah(story)?;
    lamentations(story)?;
    ezekiel(story)?;
    daniel(story)?;
    Ok(())
}

